// Wrapper de localStorage con expiración
function crearStorageConExpiracion(storage = localStorage) {
  return {
    set(clave, valor, ttlMs) {
      const item = {
        valor,
        expira: ttlMs ? Date.now() + ttlMs : null,
      };
      storage.setItem(clave, JSON.stringify(item));
    },
    get(clave, defecto = null) {
      const raw = storage.getItem(clave);
      if (!raw) return defecto;

      const item = JSON.parse(raw);
      if (item.expira && Date.now() > item.expira) {
        storage.removeItem(clave);
        return defecto; // Expirado
      }
      return item.valor;
    },
    remove: clave => storage.removeItem(clave),
  };
}

// Simulamos con un objeto en lugar de localStorage real
const mockStorage = {};
const store = crearStorageConExpiracion({
  getItem: k => mockStorage[k] ?? null,
  setItem: (k, v) => { mockStorage[k] = v; },
  removeItem: k => { delete mockStorage[k]; },
});

store.set('token', 'abc123', 1000); // Expira en 1 segundo
console.log(store.get('token')); // 'abc123'
// (1 segundo después)
// console.log(store.get('token')); // null — expirado

// Sincronizar estado entre pestañas con storage event
// (Esto normalmente solo funciona en browser)
const estadoCompartido = {
  _datos: {},
  _listeners: [],

  // Simula localStorage.setItem
  set(clave, valor) {
    this._datos[clave] = JSON.stringify(valor);
    // En browser real: localStorage.setItem lanza StorageEvent en OTRAS pestañas
    this._listeners.forEach(fn => fn({ key: clave, newValue: JSON.stringify(valor) }));
  },

  get(clave) {
    const raw = this._datos[clave];
    return raw ? JSON.parse(raw) : null;
  },

  // Simula window.addEventListener('storage', ...)
  onChange(fn) {
    this._listeners.push(fn);
  },
};

// Pestaña B escucha cambios:
estadoCompartido.onChange(({ key, newValue }) => {
  console.log(`[Pestaña B] ${key} cambió a:`, JSON.parse(newValue));
});

// Pestaña A hace cambios:
estadoCompartido.set('carrito', { items: 3 });
estadoCompartido.set('usuario', { nombre: 'Ana' });

