function crearStore(prefijo, storageSimulado = new Map()) {
  const storage = {
    getItem: k => storageSimulado.get(k) ?? null,
    setItem: (k, v) => storageSimulado.set(k, v),
    removeItem: k => storageSimulado.delete(k),
    has: k => storageSimulado.has(k),
  };

  const claveCon = clave => `${prefijo}:${clave}`;

  return {
    get(clave, defecto = null) {
      const raw = storage.getItem(claveCon(clave));
      if (raw === null) return defecto;
      try { return JSON.parse(raw); } catch { return raw; }
    },
    set(clave, valor) {
      storage.setItem(claveCon(clave), JSON.stringify(valor));
    },
    remove(clave) {
      storage.removeItem(claveCon(clave));
    },
    has(clave) {
      return storage.has(claveCon(clave));
    },
  };
}

const store = crearStore('app');

store.set('config', { tema: 'oscuro', idioma: 'es' });
store.set('contador', 42);

const config = store.get('config');
const contador = store.get('contador');
const noExiste = store.get('nada', 'defecto');
const tieneConfig = store.has('config');

store.remove('contador');
const despuesRemove = store.has('contador');

console.log(config, contador, noExiste, tieneConfig, despuesRemove);

function crearCacheVersionada(version) {
  let _version = version;
  const cache = new Map();

  return {
    guardar(url, respuesta) {
      cache.set(url, { respuesta, version: _version, timestamp: Date.now() });
    },
    obtener(url) {
      const entrada = cache.get(url);
      if (!entrada) return null;
      if (entrada.version !== _version) {
        cache.delete(url);
        return null; // Versión obsoleta
      }
      return entrada.respuesta;
    },
    invalidar(nuevaVersion) {
      cache.clear();
      if (nuevaVersion) _version = nuevaVersion;
    },
    get version() { return _version; },
    get size() { return cache.size; },
  };
}

const cache = crearCacheVersionada('v1');

cache.guardar('/api/usuarios', [{ id: 1 }, { id: 2 }]);
cache.guardar('/api/productos', [{ id: 1 }]);

const usuarios = cache.obtener('/api/usuarios');
const size1 = cache.size; // 2

cache.invalidar('v2');
const size2 = cache.size; // 0
const usuariosPost = cache.obtener('/api/usuarios'); // null

console.log('Usuarios:', usuarios?.length);
console.log('Size antes/después:', size1, size2);
console.log('Versión actual:', cache.version);

const DEFAULTS = { tema: 'claro', idioma: 'es', notificaciones: true, densidad: 'normal' };

function crearPreferencias(userId, storageSimulado = new Map()) {
  const CLAVE = `prefs:${userId}`;

  function cargar() {
    const raw = storageSimulado.get(CLAVE);
    return raw ? JSON.parse(raw) : { ...DEFAULTS };
  }

  function guardar(prefs) {
    storageSimulado.set(CLAVE, JSON.stringify(prefs));
  }

  return {
    get(clave, defecto = null) {
      const prefs = cargar();
      return clave in prefs ? prefs[clave] : defecto;
    },
    set(clave, valor) {
      const prefs = cargar();
      prefs[clave] = valor;
      guardar(prefs);
    },
    resetear() {
      guardar({ ...DEFAULTS });
    },
    getAll() {
      return { ...cargar() };
    },
  };
}

const prefs = crearPreferencias('user-123');

const temaInicial = prefs.get('tema');      // 'claro'
prefs.set('tema', 'oscuro');
prefs.set('idioma', 'en');

const temaDespues = prefs.get('tema');      // 'oscuro'
const idiomaDespues = prefs.get('idioma'); // 'en'
const todas = prefs.getAll();

prefs.resetear();
const temaReset = prefs.get('tema'); // 'claro'

console.log(temaInicial, temaDespues, idiomaDespues);
console.log('Todas:', todas);
console.log('Después de reset:', temaReset);
